// Typical Characteristics of Memory Levels (Size/Latency progression)

// L1 Cache (Per Core): Smallest, Fastest
#define L1_SIZE_KB 64
#define L1_LATENCY_CYCLES 4

// L2 Cache (Per Core/Shared): Medium size, Moderate speed
#define L2_SIZE_KB 512
#define L2_LATENCY_CYCLES 12

// L3 Cache (Shared): Large size, Slower speed
#define L3_SIZE_MB 8
#define L3_LATENCY_CYCLES 40

// DRAM (Main Memory): Largest, Slowest (1GB = 1024^3 Bytes)
#define DRAM_SIZE_GB 16
#define DRAM_LATENCY_NS 80
// Note: Size increases significantly down the hierarchy.
